import{_t as e,it as t,n,rt as r}from"./chunks/framework.BVGGWBQY.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1788874077000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="one-tool-i-expected-is-missing" tabindex="-1">One tool I expected is missing <a class="header-anchor" href="#one-tool-i-expected-is-missing" aria-label="Permalink to “One tool I expected is missing”">​</a></h2><p>Almost always the tool filter or read-only mode rather than a bug.</p><ul><li><code>CARDDAV_READ_ONLY=true</code> registers the ten read tools and nothing else.</li><li><code>CARDDAV_ALLOW_TOOLS</code> and <code>CARDDAV_DENY_TOOLS</code> narrow further — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</li></ul><p>A filtered-out tool does not exist on the protocol: it is absent from <code>tools/list</code> and a call to it answers &quot;tool not found&quot;, the same as a name that never existed. That is deliberate — a server that answered differently would tell a caller which tools it is hiding — but it does mean the absence looks like a missing feature.</p><p>If a name in the allow list matches nothing, the server does not start at all and prints the real names. So a running server with a missing tool is a server that was told to hide it.</p><h2 id="invalid-url-or-nothing-works-at-all" tabindex="-1"><code>Invalid URL</code>, or nothing works at all <a class="header-anchor" href="#invalid-url-or-nothing-works-at-all" aria-label="Permalink to “Invalid URL, or nothing works at all”">​</a></h2><p><code>CARDDAV_URL</code> is the root of the CardDAV server, not one address book and not your provider&#39;s web login. <code>https://cloud.example.net/remote.php/dav</code> for Nextcloud, <code>https://example.net/dav.php</code> for Baikal. See <a href="/guide/getting-started#finding-the-url">finding the URL</a>.</p><p>A query string or a fragment on that URL is refused at startup. It has no meaning to discovery and a real cost — relative hrefs resolve against it, and <code>?x=1/</code> spliced on the end turns <code>/dav?x=1/work/</code> into <code>/work/</code>.</p><h2 id="http-401" tabindex="-1">HTTP 401 <a class="header-anchor" href="#http-401" aria-label="Permalink to “HTTP 401”">​</a></h2><p>Most hosted services want an <strong>app-specific password</strong>, not the account password. Nextcloud, Fastmail and iCloud all issue one per application.</p><p>If <code>CARDDAV_TOKEN</code> is set, try username and password instead: almost no CardDAV server takes a bearer token, and one that does not will answer 401 without explaining why.</p><h2 id="http-405-on-everything" tabindex="-1">HTTP 405 on everything <a class="header-anchor" href="#http-405-on-everything" aria-label="Permalink to “HTTP 405 on everything”">​</a></h2><p>The URL is probably not a CardDAV endpoint. For Baikal it usually has to end in <code>/dav.php</code>; for Nextcloud, <code>/remote.php/dav</code>.</p><h2 id="search-contacts-returns-nothing-or-too-much" tabindex="-1"><code>search_contacts</code> returns nothing, or too much <a class="header-anchor" href="#search-contacts-returns-nothing-or-too-much" aria-label="Permalink to “search_contacts returns nothing, or too much”">​</a></h2><p><code>get_server_info</code> reports whether server-side search works at all on this instance — it probes rather than trusting what the server advertises.</p><p>Where the server cannot filter, this server fetches the collection and matches locally instead, and the answer says <code>matched_with: &quot;client-filter&quot;</code> so a slow search has a visible reason. Where the server <em>can</em> filter, the result is still re-checked here, because a server that filters partially is indistinguishable from one that matched properly, and the note says how many entries were dropped.</p><h2 id="a-group-i-can-see-in-my-phone-is-not-in-list-groups" tabindex="-1">A group I can see in my phone is not in <code>list_groups</code> <a class="header-anchor" href="#a-group-i-can-see-in-my-phone-is-not-in-list-groups" aria-label="Permalink to “A group I can see in my phone is not in list_groups”">​</a></h2><p>Almost certainly the other group convention — but this server reads both, so the more likely causes are:</p><ul><li>The group lives in an address book <code>CARDDAV_ADDRESSBOOKS</code> withheld. <code>list_address_books</code> reports how many it is hiding.</li><li>The card is in a different address book from its members. A group can only name cards in its own collection; members elsewhere show up as <code>unresolved</code> in <code>get_group</code>.</li></ul><h2 id="a-contact-has-no-birthday-year" tabindex="-1">A contact has no birthday year <a class="header-anchor" href="#a-contact-has-no-birthday-year" aria-label="Permalink to “A contact has no birthday year”">​</a></h2><p>That is the card, not the server. <code>BDAY:--0415</code> means &quot;15 April, year unknown&quot;, which is what a phone writes when the year was never entered. It comes back as <code>{ month: 4, day: 15 }</code> with no <code>year</code> — deliberately, rather than being dropped for being incomplete or given an invented one.</p><p>Writing one back into a <strong>vCard 3.0</strong> book uses the year <code>1604</code>, because RFC 2426 has no syntax for a yearless date and 1604 is the placeholder clients settled on for exactly this. The answer says so when it happens.</p><h2 id="get-contact-photo-refuses" tabindex="-1"><code>get_contact_photo</code> refuses <a class="header-anchor" href="#get-contact-photo-refuses" aria-label="Permalink to “get_contact_photo refuses”">​</a></h2><p>Two reasons, and the message says which.</p><p>The card stores its photo as a <strong>link</strong> rather than embedding it. This server reports the address and does not follow it: that address was chosen by whoever wrote the card, and fetching it would make this process a request forwarder pointed at an arbitrary host.</p><p>Or the photo is past the half-megabyte ceiling this tool applies. <code>get_contact</code> reports the size without fetching anything.</p><p>That ceiling is deliberately well under the one-mebibyte ceiling on reading a card at all, and the gap is base64: an embedded photo costs a third more inside the card than it does as bytes. A tool ceiling set above the read ceiling is a tool ceiling that never fires — the read refuses first, with a message about byte counts instead of one naming the tool that can help.</p><h2 id="everything-is-partial-true" tabindex="-1">Everything is <code>partial: true</code> <a class="header-anchor" href="#everything-is-partial-true" aria-label="Permalink to “Everything is partial: true”">​</a></h2><p>That is <code>list_contacts</code> working as intended. A listing asks the server for a dozen named properties rather than for whole cards, which is the difference between kilobytes and megabytes on a real address book. <code>get_contact</code> returns the whole card.</p><p>Nothing is lost by it: the write tools never build on a partial card, they fetch the whole thing first.</p><h2 id="a-card-in-my-address-book-cannot-be-read" tabindex="-1">A card in my address book cannot be read <a class="header-anchor" href="#a-card-in-my-address-book-cannot-be-read" aria-label="Permalink to “A card in my address book cannot be read”">​</a></h2><p><code>list_contacts</code> reports how many cards it could not parse and carries on rather than failing the whole listing. They are usually old exports from a client that wrote something no parser accepts.</p><p><code>export_contacts</code> still returns them, because it hands over the raw vCard text without parsing it — which is also why it is the right tool for finding out what is wrong with one.</p><p>If <strong>every</strong> card in every book is counted that way and the listing is empty, that is not a collection of bad exports — it is the reader and the server disagreeing about how the card was packed into the response. Versions before 0.1.3 did that against Open-Xchange, which mailbox.org runs: the card arrives inside a <code>&lt;![CDATA[…]]&gt;</code> section, and <code>address-data</code> is read as raw source, so the section markers were part of what went to the vCard parser. Upgrading is the fix; there is no setting for it.</p><h2 id="where-the-untrusted-marker-is-and-is-not" tabindex="-1">Where the untrusted marker is, and is not <a class="header-anchor" href="#where-the-untrusted-marker-is-and-is-not" aria-label="Permalink to “Where the untrusted marker is, and is not”">​</a></h2><p>Every answer built from card content carries <code>untrusted: true</code> and <code>source: &quot;carddav&quot;</code> as <strong>fields</strong>, not only as a sentence, so a client can check rather than notice.</p><p>Two tools deliberately do not: <code>get_server_info</code> and <code>list_changes</code> return this server&#39;s own words — protocol tokens, ids, counts — with no card content in them at all. A marker on everything would be a marker on nothing.</p>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};